class Producto:
    """Producto del inventario con su precio final."""

    igv = 0.18  # atributo de clase: igual para todos

    def __init__(self, nombre, precio):
        self.nombre = nombre
        self.precio = precio

    def precio_final(self):
        return self.precio * (1 + self.igv)

    def __repr__(self):
        return f"Producto({self.nombre!r}, {self.precio})"


p = Producto("mouse", 50)
print(p)
print(p.precio_final())

class Carrito:
    """Carrito de compras con una lista propia por instancia."""

    def __init__(self, cliente):
        self.cliente = cliente
        self.items = []  # lista nueva para cada carrito

    def agregar(self, nombre, precio):
        self.items.append((nombre, precio))
        return len(self.items)

    def total(self):
        return sum(precio for _, precio in self.items)

    def __repr__(self):
        return f"Carrito({self.cliente!r}, {len(self.items)} items)"


ana = Carrito("Ana")
luis = Carrito("Luis")
ana.agregar("teclado", 120)
ana.agregar("mouse", 45)
luis.agregar("monitor", 300)
print(ana, ana.total())
print(luis, luis.total())

class Inventario:
    """Controla el stock con operaciones validadas."""

    def __init__(self):
        self._stock = {}

    def entrar(self, producto, cantidad):
        if cantidad <= 0:
            raise ValueError("La cantidad debe ser positiva")
        self._stock[producto] = self._stock.get(producto, 0) + cantidad

    def salir(self, producto, cantidad):
        disponible = self._stock.get(producto, 0)
        if cantidad > disponible:
            raise ValueError(f"Stock insuficiente: hay {disponible}")
        self._stock[producto] = disponible - cantidad

    def consultar(self, producto):
        return self._stock.get(producto, 0)

    def __repr__(self):
        return f"Inventario({self._stock})"


inv = Inventario()
inv.entrar("mouse", 10)
inv.salir("mouse", 3)
print(inv.consultar("mouse"))
print(inv)

