class Punto {
public:
    Punto(double x, double y) : x_(x), y_(y) {}

    double norma() const {
        return std::sqrt(x_ * x_ + y_ * y_);
    }

private:
    double x_;
    double y_;
};

int main() {
    Punto p(3, 4);
    std::cout << p.norma() << std::endl;
    return 0;
