class Cuenta:
    """Cuenta con saldo privado por convención."""

    def __init__(self, titular):
        self.titular = titular
        self._saldo = 0

    def depositar(self, monto):
        if monto <= 0:
            raise ValueError("El monto debe ser positivo")
        self._saldo += monto

    def retirar(self, monto):
        if monto > self._saldo:
            raise ValueError("Saldo insuficiente")
        self._saldo -= monto

    def __repr__(self):
        return f"Cuenta({self.titular!r}, saldo={self._saldo})"


c = Cuenta("Ada")
c.depositar(100)
c.retirar(30)
print(c)

